import { existsSync, readFileSync, rmSync } from "node:fs";
import { join } from "node:path";
import {
	countLines,
	filterSourceRanges,
	mergeRanges,
	parseDiffRanges,
	toStrykerMutateArgs,
	type LineRange,
} from "./diff-ranges.ts";

/**
 * Mutation testing scoped to what Render actually changed.
 *
 * Coverage answers "did anything execute this line". It cannot answer "does any
 * test *object* when this line is wrong" — a loosened matcher or a fixture edited
 * to match wrong output keeps coverage at 100%. That gap is the failure mode A
 * spends turns hunting by reading, and mutation answers it mechanically.
 *
 * This is a signal, not a gate. A survived mutant is sometimes an equivalent
 * mutant — semantically identical, unkillable, and correctly ignored. Deciding
 * which is which is a judgment, so survivors are handed to the reviewer to
 * adjudicate rather than blocking the phase.
 */

export type MutateStatus = "ran" | "skipped" | "error";

export interface Survivor {
	file: string;
	line: number;
	mutator: string;
	replacement: string;
	/** Test files that executed this line and still passed. Empty means nothing covered it. */
	covered_by: string[];
}

export interface MutateResult {
	status: MutateStatus;
	/** Why nothing ran. Absent when `status` is "ran". */
	reason?: "no-backend" | "no-changes" | "oversize" | "timeout" | "failed";
	backend?: "stryker";
	tested?: number;
	killed?: number;
	survived?: number;
	no_coverage?: number;
	survivors?: Survivor[];
	lines_scoped?: number;
	duration_ms?: number;
	detail?: string;
}

/** Stryker's JSON report, narrowed to the fields consumed here. */
interface StrykerReport {
	files: Record<string, { mutants: Array<{ mutatorName: string; replacement: string; status: string; coveredBy?: string[]; location: { start: { line: number } } }> }>;
	testFiles?: Record<string, { tests: Array<{ id: string; name?: string }> }>;
}

export const DEFAULT_TIMEOUT_SEC = 60;
const REPORT_PATH = join("reports", "mutation", "mutation.json");

/** Source globs to mutate, and the test patterns to keep out of the mutation set. */
export const DEFAULT_INCLUDE = [/^src\/.*\.(ts|tsx|js|jsx|mjs|cjs)$/];
export const DEFAULT_EXCLUDE = [/\.(test|spec)\.(ts|tsx|js|jsx|mjs|cjs)$/, /^test\//, /^tests\//, /^__tests__\//];

/**
 * Map Stryker test ids back to the files that own them. Survivors are far more
 * actionable when the reviewer can see which suite ran and still passed.
 */
function testFileById(report: StrykerReport): Map<string, string> {
	const map = new Map<string, string>();
	for (const [file, entry] of Object.entries(report.testFiles ?? {})) {
		for (const t of entry.tests ?? []) map.set(t.id, file);
	}
	return map;
}

export function parseStrykerReport(report: StrykerReport): {
	tested: number;
	killed: number;
	survived: number;
	no_coverage: number;
	survivors: Survivor[];
} {
	const byId = testFileById(report);
	let killed = 0;
	let survived = 0;
	let noCoverage = 0;
	const survivors: Survivor[] = [];
	for (const [file, entry] of Object.entries(report.files ?? {})) {
		for (const m of entry.mutants ?? []) {
			// Timeouts count as killed: the mutant changed behaviour enough to hang the
			// suite, which is detection, just an ugly form of it.
			if (m.status === "Killed" || m.status === "Timeout") killed += 1;
			else if (m.status === "NoCoverage") noCoverage += 1;
			else if (m.status === "Survived") {
				survived += 1;
				const files = [...new Set((m.coveredBy ?? []).map((id) => byId.get(id)).filter((f): f is string => !!f))];
				survivors.push({
					file,
					line: m.location.start.line,
					mutator: m.mutatorName,
					replacement: m.replacement,
					covered_by: files,
				});
			}
			// Ignored / CompileError / RuntimeError are counted in neither: they say
			// nothing about test quality, only about the mutant being unrunnable.
		}
	}
	return { tested: killed + survived + noCoverage, killed, survived, no_coverage: noCoverage, survivors };
}

export interface RunOptions {
	cwd: string;
	base: string;
	timeoutSec?: number;
	maxLines?: number;
	/** Injected so the runner is testable without a git repo or a real Stryker run. */
	gitDiff?: (cwd: string, base: string) => string;
	/**
	 * Untracked files and their line counts. `git diff` does not report untracked
	 * files at all, so without this a brand-new source file — the code most likely
	 * to have thin tests — would scope to nothing and skip silently.
	 */
	untracked?: (cwd: string) => Array<{ file: string; lines: number }>;
	runStryker?: (cwd: string, mutateArgs: string[], timeoutSec: number) => { ok: boolean; timedOut: boolean; detail?: string };
}

/**
 * Cap on scoped lines. Mutation cost scales with mutant count, and mutant count
 * with changed lines — past a point the run stops being the cheap signal it is
 * meant to be. A diff this large is usually a rename or a generated file, where
 * the result would be noise anyway.
 */
export const DEFAULT_MAX_LINES = 2000;

export function computeRanges(diff: string, untracked: Array<{ file: string; lines: number }> = []): LineRange[] {
	const fromDiff = parseDiffRanges(diff);
	// An untracked file is entirely new, so every line of it is in scope.
	const fromNew = untracked.filter((u) => u.lines > 0).map((u) => ({ file: u.file, start: 1, end: u.lines }));
	return mergeRanges(filterSourceRanges([...fromDiff, ...fromNew], { include: DEFAULT_INCLUDE, exclude: DEFAULT_EXCLUDE }));
}

export function runMutate(opts: RunOptions): MutateResult {
	const { cwd, base } = opts;
	const timeoutSec = opts.timeoutSec ?? DEFAULT_TIMEOUT_SEC;
	const maxLines = opts.maxLines ?? DEFAULT_MAX_LINES;

	// No Stryker config means this repo has not opted in. Silence, not failure:
	// most repos have not, and Render must not break because of it.
	if (!existsSync(join(cwd, "stryker.config.json")) && !existsSync(join(cwd, "stryker.conf.json"))) {
		return { status: "skipped", reason: "no-backend" };
	}

	const diff = opts.gitDiff!(cwd, base);
	const ranges = computeRanges(diff, opts.untracked?.(cwd) ?? []);
	if (ranges.length === 0) return { status: "skipped", reason: "no-changes" };

	const lines = countLines(ranges);
	if (lines > maxLines) {
		return { status: "skipped", reason: "oversize", lines_scoped: lines };
	}

	const started = Date.now();
	const outcome = opts.runStryker!(cwd, toStrykerMutateArgs(ranges), timeoutSec);
	const duration = Date.now() - started;

	if (outcome.timedOut) {
		return { status: "skipped", reason: "timeout", lines_scoped: lines, duration_ms: duration };
	}

	const reportPath = join(cwd, REPORT_PATH);
	if (!existsSync(reportPath)) {
		return { status: "error", reason: "failed", detail: outcome.detail ?? "no mutation report produced", duration_ms: duration };
	}
	let report: StrykerReport;
	try {
		report = JSON.parse(readFileSync(reportPath, "utf8")) as StrykerReport;
	} catch (err) {
		return { status: "error", reason: "failed", detail: `unreadable report: ${String(err)}`, duration_ms: duration };
	}
	const parsed = parseStrykerReport(report);
	return { status: "ran", backend: "stryker", lines_scoped: lines, duration_ms: duration, ...parsed };
}

/** Remove a stale report so a failed run cannot be read as the current one. */
export function clearReport(cwd: string): void {
	rmSync(join(cwd, REPORT_PATH), { force: true });
}

src/diff-ranges.ts.source:
/**
 * Changed-line ranges from a git diff, in the form mutation testing needs.
 *
 * Scoping mutation to the lines Render actually touched is what makes it cheap
 * enough to run every time — a 20-line range costs ~2s against ~44s for a whole
 * source tree — and, more importantly, what makes the result readable. Mutating
 * whole files surfaces pre-existing survivors that Render did not cause, and
 * those drown the ones it did.
 *
 * The parsing is small but the edge cases are not, so it lives apart from the
 * runner and is tested directly: an off-by-one here silently mutates the wrong
 * code and reports confidently about it.
 */

export interface LineRange {
	file: string;
	start: number;
	end: number;
}

/** `@@ -oldStart,oldCount +newStart,newCount @@` — counts are omitted when 1. */
const HUNK = /^@@ -\d+(?:,\d+)? \+(\d+)(?:,(\d+))? @@/;
// `b/` is optional so that `+++ /dev/null` matches too. It must: a deleted file
// needs to clear the current file, and if the header does not match at all the
// previous file stays current and the deletion's hunks are attributed to it.
// Deletions happen to carry `+0,0` hunks that are dropped anyway, so this was
// previously correct only by luck.
const FILE_HEADER = /^\+\+\+ (?:b\/)?(.+)$/;

/**
 * Parse `git diff --unified=0` output into per-file added/modified line ranges.
 *
 * Only `+` side lines matter: a mutation range must point at code that exists in
 * the working tree. A pure deletion (`+0,0`) yields no range — there is nothing
 * left to mutate — which is correct, not an omission.
 */
export function parseDiffRanges(diff: string): LineRange[] {
	const ranges: LineRange[] = [];
	let file: string | null = null;
	for (const line of diff.split("\n")) {
		const header = FILE_HEADER.exec(line);
		if (header) {
			// `/dev/null` on the + side means the file was deleted; nothing to mutate.
			file = header[1] === "/dev/null" ? null : header[1];
			continue;
		}
		if (!file) continue;
		const hunk = HUNK.exec(line);
		if (!hunk) continue;
		const start = Number(hunk[1]);
		// An absent count means exactly one line. A count of zero means the change
		// was a deletion anchored after `start`, so there is no new line to mutate.
		const count = hunk[2] === undefined ? 1 : Number(hunk[2]);
		if (count === 0) continue;
		ranges.push({ file, start, end: start + count - 1 });
	}
	return ranges;
}

/**
 * Keep only ranges in files worth mutating: source, not tests, and matching the
 * caller's source globs. Mutating a test file is meaningless — the mutant would
 * be "killed" by definition or break the run.
 */
export function filterSourceRanges(
	ranges: LineRange[],
	opts: { include: RegExp[]; exclude: RegExp[] },
): LineRange[] {
	return ranges.filter(
		(r) => opts.include.some((re) => re.test(r.file)) && !opts.exclude.some((re) => re.test(r.file)),
	);
}

/**
 * Merge ranges that touch or overlap within a file. Adjacent diff hunks often
 * abut after filtering, and collapsing them keeps the `--mutate` argument short
 * enough to stay under argv limits on a large diff.
 */
export function mergeRanges(ranges: LineRange[]): LineRange[] {
	const byFile = new Map<string, LineRange[]>();
	for (const r of ranges) {
		const list = byFile.get(r.file) ?? [];
		list.push(r);
		byFile.set(r.file, list);
	}
	const out: LineRange[] = [];
	for (const [file, list] of [...byFile.entries()].sort((a, b) => a[0].localeCompare(b[0]))) {
		list.sort((a, b) => a.start - b.start);
		let cur = { ...list[0] };
		for (const r of list.slice(1)) {
			// `<= cur.end + 1` merges abutting ranges, not just overlapping ones.
			if (r.start <= cur.end + 1) {
				cur.end = Math.max(cur.end, r.end);
			} else {
				out.push(cur);
				cur = { ...r };
			}
		}
		out.push(cur);
		void file;
	}
	return out;
}

/**
 * Stryker's mutation-range syntax: `file:startLine:startCol-endLine:endCol`.
 * Column 1 to column 1 of the following line covers a whole line inclusively.
 */
export function toStrykerMutateArgs(ranges: LineRange[]): string[] {
	return ranges.map((r) => `${r.file}:${r.start}:1-${r.end + 1}:1`);
}

/** Total lines covered, for the size cap that decides whether to run at all. */
export function countLines(ranges: LineRange[]): number {
	return ranges.reduce((sum, r) => sum + (r.end - r.start + 1), 0);
}

test/store.test.ts.source:
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";
import assert from "node:assert/strict";
import { Store, diagnose, modelTotals, summarize, phaseTotalsByVersion } from "../src/store.ts";
import { computeSeams } from "../src/schema.ts";
import type { PriceTable } from "../src/pricing.ts";

// Empty by default so tests never depend on whatever happens to be in this
// machine's real `~/.pi/agent/models-store.json`. Pass a table explicitly for
// tests about pricing itself.
function tmpStore(prices: PriceTable = new Map()): { store: Store; cleanup: () => void } {
	const dir = mkdtempSync(join(tmpdir(), "craft-metrics-"));
	return {
		store: new Store(join(dir, "events.jsonl"), prices),
		cleanup: () => rmSync(dir, { recursive: true, force: true }),
	};
}

test("usage between enter/exit lands on that phase", () => {
	const { store: s, cleanup } = tmpStore();
	try {
		const run = s.openRun({ host: "pi", cwd: "/tmp/demo", repo: "demo", mode: "full" });
		s.enterPhase(run.run_id, "C", { agent: "craft-planner", at: "2026-04-08T10:00:00.000Z" });
		s.recordUsage(run.run_id, {
			at: "2026-04-08T10:00:05.000Z",
			model: "zai/glm-5.2",
			cost_usd: 0.01,
			tokens: { input: 100, output: 50 },
			turns: 1,
		});
		s.exitPhase(run.run_id, "C", { security_triggers: ["untrusted-input"] }, "2026-04-08T10:01:00.000Z");
		const got = s.get(run.run_id)!;
		const c = got.phases.find((p) => p.name === "C")!;
		assert.equal(c.cost_usd, 0.01);
		assert.equal(c.tokens.input, 100);
		assert.equal(c.duration_ms, 60_000);
		assert.deepEqual(c.security_triggers, ["untrusted-input"]);
		assert.equal(got.open_phase, null);
	} finally {
		cleanup();
	}
});

test("usage with no open phase and no agent is unattributed", () => {
	const { store: s, cleanup } = tmpStore();
	try {
		const run = s.openRun({ host: "pi", cwd: "/tmp/demo", repo: "demo", mode: "full" });
		s.recordUsage(run.run_id, { cost_usd: 0.5, model: "zai/glm-5.2", turns: 1 });
		const got = s.get(run.run_id)!;
		const u = got.phases.find((p) => p.name === "unattributed")!;
		assert.equal(u.cost_usd, 0.5);
		assert.ok(!got.phases.find((p) => p.name === "C"));
	} finally {
		cleanup();
	}
});

test("named agent maps to phase when skill is late", () => {
	const { store: s, cleanup } = tmpStore();
	try {
		const run = s.openRun({ host: "pi", cwd: "/tmp/demo", repo: "demo", mode: "full" });
		s.recordUsage(run.run_id, {
			agent: "craft-evaluator",
			model: "xai/grok-4.6",
			cost_usd: 0.2,
			subagent: true,
			turns: 1,
		});
		const got = s.get(run.run_id)!;
		const a = got.phases.find((p) => p.name === "A")!;
		assert.equal(a.cost_usd, 0.2);
		assert.equal(a.child_cost_usd, 0.2);
		assert.equal(a.subagent_count, 1);
		assert.equal(a.model, "xai/grok-4.6");
	} finally {
		cleanup();
	}
});

test("open phase wins over agent map (builder during F)", () => {
	const { store: s, cleanup } = tmpStore();
	try {
		const run = s.openRun({ host: "pi", cwd: "/tmp/demo", repo: "demo", mode: "full" });
		s.enterPhase(run.run_id, "F", { agent: "craft-builder" });
		s.recordUsage(run.run_id, { agent: "craft-builder", cost_usd: 0.03, turns: 1 });
		const got = s.get(run.run_id)!;
		assert.equal(got.phases.find((p) => p.name === "F")!.cost_usd, 0.03);
		assert.ok(!got.phases.find((p) => p.name === "R"));
	} finally {
		cleanup();
	}
});

test("entering a new phase closes the previous one", () => {
	const { store: s, cleanup } = tmpStore();
	try {
		const run = s.openRun({ host: "pi", cwd: "/tmp/demo", repo: "demo", mode: "full" });
		s.enterPhase(run.run_id, "R", { at: "2026-04-08T11:00:00.000Z" });
		s.enterPhase(run.run_id, "A", { at: "2026-04-08T11:10:00.000Z" });
		const got = s.get(run.run_id)!;
		assert.equal(got.open_phase, "A");
		assert.equal(got.phases.find((p) => p.name === "R")!.duration_ms, 600_000);
	} finally {
		cleanup();
	}
});

test("concurrent appends from two stores do not clobber", () => {
	const { store: a, cleanup } = tmpStore();
	try {
		const b = new Store(a.path);
		const run = a.openRun({ host: "pi", cwd: "/tmp/demo", repo: "demo", mode: "full" });
		a.enterPhase(run.run_id, "R");
		b.recordUsage(run.run_id, { cost_usd: 0.07, turns: 1, tool_name: "bash" });
		const r = a.get(run.run_id)!.phases.find((p) => p.name === "R")!;
		assert.equal(r.cost_usd, 0.07);
		assert.equal(r.tool_calls_by_name.bash, 1);
	} finally {
		cleanup();
	}
});

test("seams detect same-family collapse and cross-family pass", () => {
	const { store: s, cleanup } = tmpStore();
	try {
		const run = s.openRun({ host: "pi", cwd: "/tmp/demo", repo: "demo", mode: "full" });
		s.enterPhase(run.run_id, "C");
		s.recordUsage(run.run_id, { model: "zai/glm-5.2" });
		s.exitPhase(run.run_id, "C");
		s.enterPhase(run.run_id, "counsel");
		s.recordUsage(run.run_id, { model: "zai/glm-5.2" });
		s.exitPhase(run.run_id, "counsel");
		s.enterPhase(run.run_id, "R");
		s.recordUsage(run.run_id, { model: "zai/glm-5.2" });
		s.exitPhase(run.run_id, "R");
		s.enterPhase(run.run_id, "A");
		s.recordUsage(run.run_id, { model: "xai/grok-4.6" });
		s.exitPhase(run.run_id, "A", { verdict: "pass" });
		const got = s.get(run.run_id)!;
		assert.equal(got.seams.counsel_family_differs_from_c, false);
		assert.equal(got.seams.a_family_differs_from_r, true);
		assert.equal(got.seams.t_family_differs_from_r, null);
		assert.deepEqual(computeSeams(got), got.seams);
	} finally {
		cleanup();
	}
});

test("HITL pause accumulates wall time", () => {
	const { store: s, cleanup } = tmpStore();
	try {
		const run = s.openRun({ host: "pi", cwd: "/tmp/demo", repo: "demo", mode: "hitl" });
		s.pauseHitl(run.run_id, "2026-04-08T12:00:00.000Z");
		s.resumeHitl(run.run_id, "2026-04-08T12:05:00.000Z");
		const got = s.get(run.run_id)!;
		assert.equal(got.hitl.pause_ms, 300_000);
		assert.equal(got.outcome, "open");
	} finally {
		cleanup();
	}
});

test("mode switch full → hitl", () => {
	const { store: s, cleanup } = tmpStore();
	try {
		const run = s.openRun({ host: "pi", cwd: "/tmp/demo", repo: "demo", mode: "full" });
		s.setMode(run.run_id, "hitl");
		assert.equal(s.get(run.run_id)!.mode, "hitl");
	} finally {
		cleanup();
	}
});

test("mode lite is recorded", () => {
	const { store: s, cleanup } = tmpStore();
	try {
		const run = s.openRun({ host: "pi", cwd: "/tmp/demo", repo: "demo", mode: "lite" });
		assert.equal(s.get(run.run_id)!.mode, "lite");
	} finally {
		cleanup();
	}
});

test("tool counts and quota errors stay on the open phase", () => {
	const { store: s, cleanup } = tmpStore();
	try {
		const run = s.openRun({ host: "pi", cwd: "/tmp/demo", repo: "demo", mode: "full" });
		s.enterPhase(run.run_id, "R");
		s.recordUsage(run.run_id, { tool_name: "read" });
		s.recordUsage(run.run_id, { tool_name: "read" });
		s.recordUsage(run.run_id, { tool_name: "bash", quota_error: true, failover: true });
		const r = s.get(run.run_id)!.phases.find((p) => p.name === "R")!;
		assert.equal(r.tool_calls, 3);
		assert.equal(r.tool_calls_by_name.read, 2);
		assert.equal(r.quota_errors, 1);
		assert.equal(r.failovers, 1);
	} finally {
		cleanup();
	}
});

test("kind is set on start and filled in on reuse if missing", () => {
	const { store: s, cleanup } = tmpStore();
	try {
		const opened = s.openRun({ host: "pi", cwd: "/tmp/demo", repo: "demo", mode: "full" });
		assert.equal(opened.kind, undefined);
		const filled = s.openRun({
			host: "pi",
			cwd: "/tmp/demo",
			repo: "demo",
			mode: "full",
			kind: "bugfix",
		});
		assert.equal(filled.run_id, opened.run_id);
		assert.equal(filled.kind, "bugfix");
	} finally {
		cleanup();
	}
});

test("kind can be corrected after start", () => {
	const { store: s, cleanup } = tmpStore();
	try {
		const run = s.openRun({ host: "pi", cwd: "/tmp/demo", repo: "demo", mode: "full", kind: "scaffold" });
		assert.equal(run.kind, "scaffold");
		s.setKind(run.run_id, "feature");
		assert.equal(s.get(run.run_id)!.kind, "feature");
	} finally {
		cleanup();
	}
});

test("latestOpenForCwd returns the newest open run", () => {
	const { store: s, cleanup } = tmpStore();
	try {
		const first = s.openRun({ host: "pi", cwd: "/tmp/a", repo: "a", mode: "full" });
		const reused = s.openRun({ host: "pi", cwd: "/tmp/a", repo: "a", mode: "full" });
		assert.equal(reused.run_id, first.run_id);
		const other = s.openRun({ host: "pi", cwd: "/tmp/b", repo: "b", mode: "full" });
		assert.equal(s.latestOpenForCwd("/tmp/a")?.run_id, first.run_id);
		assert.equal(s.latestOpenForCwd("/tmp/b")?.run_id, other.run_id);
	} finally {
		cleanup();
	}
});

test("lite mode refuses counsel and T phase_enter", () => {
	const { store: s, cleanup } = tmpStore();
	try {
		const run = s.openRun({ host: "pi", cwd: "/tmp/lite", repo: "demo", mode: "lite" });
		assert.throws(() => s.enterPhase(run.run_id, "counsel"), /mode=lite/);
		assert.throws(() => s.enterPhase(run.run_id, "T"), /mode=lite/);
		// C is unaffected — the guard is scoped to counsel/T only.
		s.enterPhase(run.run_id, "C", { agent: "craft-planner" });
		assert.equal(s.get(run.run_id)!.open_phase, "C");
	} finally {
		cleanup();
	}
});

test("a stamped phase beats the phase that happens to be open", () => {
	const { store: s, cleanup } = tmpStore();
	try {
		// The exact shape that lost $41.80: work done under R, reported after A opened.
		const run = s.openRun({ host: "pi", cwd: "/tmp/demo", repo: "demo", mode: "full" });
		s.enterPhase(run.run_id, "R");
